async function telegram(helpers, text) {
  const token = $env.TELEGRAM_BOT_TOKEN, chat = $env.TELEGRAM_STAFF_CHAT_ID;
  if (!token || !chat) return false;
  await helpers.httpRequest({ method: 'POST', url: 'https://api.telegram.org/bot' + token + '/sendMessage', body: { chat_id: chat, text }, json: true, timeout: 10000 });
  return true;
}

const e = $input.first().json;
const wf = e.workflow?.name || '?', node = e.execution?.lastNodeExecuted || '?';
const msg = e.execution?.error?.message || 'sin mensaje';
const base = ($env.N8N_PUBLIC_URL || 'http://localhost:5678');
const text = 'n8n: fallo en ' + wf + ' / nodo ' + node + '\nerror: ' + msg + '\nejecucion: ' + (e.execution?.id || '?') + '\n' + base + '/workflow/' + (e.workflow?.id || '') + '/executions/' + (e.execution?.id || '');
try { await telegram(this.helpers, text); } catch (err) { /* Telegram es opcional */ }
return [{ json: { to: $env.N8N_ERROR_EMAIL || 'devs@bandada.localhost', subject: '[n8n] Fallo en ' + wf, text, html: '<pre>' + text.replace(/</g, '&lt;') + '</pre>' } }];
